from easyvolcap.utils.base_utils import dotdict
from easyvolcap.utils.data_utils import to_cuda as data_utils_to_cuda
import torch

# If batch is a tuple or list, recursively apply to_cuda to each element
if isinstance(batch, (tuple, list)):
    return type(batch)(to_cuda(item, device, ignore_list) for item in batch)

# If batch is a dictionary, recursively apply to_cuda to each value, except for "meta" keys
elif isinstance(batch, dict):
    # Convert the dictionary to a dotdict for easier access
    batch = dotdict(batch)
    for key, value in batch.items():
        if key != "meta":
            batch[key] = to_cuda(value, device, ignore_list)
    return batch

